sp_BuscarConfigFiscal	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_BuscarConfigFiscal`(IN p_idEmpresa INT)\nBEGIN\n\n    SELECT idEmpresaConfigFiscal, idEmpresa, cnpjFiscal, inscricaoEstadual, inscricaoMunicipal,\n\n           regimeTributario, ambiente, serieNFe, serieNFCe, proximoNumNFe, proximoNumNFCe,\n\n           aliqPadraoICMS, aliqPadraoPIS, aliqPadraoCOFINS,\n\n           CASE WHEN certificadoA1 IS NOT NULL THEN 1 ELSE 0 END AS temCertificado,\n\n           dthVencCertificado, fAtivo, dthAtualizacao\n\n    FROM EmpresaConfigFiscal\n\n    WHERE idEmpresa = p_idEmpresa;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
